(function(){const scenarios=[],assert=(v,m)=>{if(!v)throw Error(m);},run=(name,fn)=>{fn();scenarios.push(name);};let model,api,original;
 run('native command deletes all sixteen types with exact undo identity',()=>{nativeInit(0,{series:[]});model=nativeModel;api=nativeAPI;for(const type of Aster.DRAWING_TYPES)api.addDrawing({id:type,type,points:['longposition','shortposition'].includes(type)?[{time:10.25,price:20},{time:10.25,price:type==='longposition'?19:21},{time:10.25,price:type==='longposition'?22:18},{time:11.25,price:20}]:Array.from({length:type==='freehand'?4:Aster.drawingPointCount(type)},(_,i)=>({time:i+.25,price:5+i})),...(type==='text'?{text:'held'}:{})});original=model.drawings.items.slice();const serial=model.drawings.serial,history=model.drawings.undoStack.length,r=nativeCommand('deleteDrawings',[Aster.DRAWING_TYPES]);assert(r.changed===16&&!r.invalidationFailed&&model.drawings.items.length===0,'delete receipt');assert(model.drawings.undoStack.length===history+1&&model.drawings.serial===serial&&model.drawings.selected===null,'history and selection');api.undo();assert(model.drawings.items.every((d,i)=>d===original[i]),'exact identity');api.redo();assert(model.drawings.items.length===0,'redo');api.undo();});
 run('orphan removal and nonwritable selection stay atomic',()=>{model.drawings.add({id:'orphan',type:'horizontal',panel:'missing',axisId:'old-axis',seriesId:'old-series',points:[{time:1,price:2}]});const items=model.drawings.items,u=model.drawings.undoStack;Object.defineProperty(model.drawings,'selected',{value:'orphan',writable:false,configurable:true});let threw=false;try{api.deleteDrawings(['trendline','orphan']);}catch{threw=true;}assert(threw&&items===model.drawings.items&&u===model.drawings.undoStack,'selection atomic');Object.defineProperty(model.drawings,'selected',{writable:true});const receipt=api.deleteDrawings(['trendline','orphan']);assert(receipt.changed===2&&model.drawings.selected===null,'orphan and mixed removal');});
 run('observer reentry and exception preserve deletion then listener cleanup',()=>{api.invalidate=()=>{api.invalidate=()=>{};api.deleteDrawings(['horizontal']);throw Error('observer');};const r=api.deleteDrawings(['text']);assert(r.changed===1&&r.invalidationFailed,'outer receipt');assert(!model.drawings.items.some(d=>d.id==='text'||d.id==='horizontal'),'reentry survives');const store=model.store;model.dispose();assert(store.listeners.size===0,'listeners');});
 return JSON.stringify({case:'drawing-delete-quickjs',passed:true,checks:3,scenarios});})()
